namespace Essco.Application.HumanResources;
public sealed record VacationInput(string EmployeeId,DateOnly From,DateOnly To,decimal Days,string Comments);
public sealed record DisabilityInput(string EmployeeId,DateOnly From,DateOnly To,decimal Days,string Voucher,string Detail,string Type);
public sealed record DeductionInput(string EmployeeId,string Category,decimal Amount,string Detail,DateOnly Date,int FirstPercentage,int SecondPercentage);
public sealed record LoanInput(string EmployeeId,string EmployeeName,DateOnly Date,decimal Amount,string Type,string Detail,decimal FortnightPayment);
public interface IEmployeeMovementRepository{ValueTask<int>SaveVacationAsync(VacationInput x,CancellationToken t);ValueTask<int>SaveDisabilityAsync(DisabilityInput x,CancellationToken t);ValueTask<int>SaveDeductionAsync(DeductionInput x,CancellationToken t);ValueTask<int>SaveLoanAsync(LoanInput x,CancellationToken t);ValueTask<bool>AnnulAsync(string type,int number,CancellationToken t);}
public sealed class EmployeeMovementService(IEmployeeMovementRepository repository)
{public async ValueTask<(bool Succeeded,int Number,string?Error)>SaveVacationAsync(VacationInput x,CancellationToken t){if(x.From>x.To||x.Days<=0)return(false,0,"Fechas o días inválidos.");var n=await repository.SaveVacationAsync(x,t);return(n>0,n,n>0?null:"No se guardó la vacación.");}public async ValueTask<(bool Succeeded,int Number,string?Error)>SaveDisabilityAsync(DisabilityInput x,CancellationToken t){if(x.From>x.To||x.Days<=0)return(false,0,"Fechas o días inválidos.");var n=await repository.SaveDisabilityAsync(x,t);return(n>0,n,n>0?null:"No se guardó la incapacidad.");}public async ValueTask<(bool Succeeded,int Number,string?Error)>SaveDeductionAsync(DeductionInput x,CancellationToken t){if(x.Amount<=0||x.FirstPercentage<0||x.SecondPercentage<0||x.FirstPercentage+x.SecondPercentage!=100)return(false,0,"Monto o distribución quincenal inválidos.");var n=await repository.SaveDeductionAsync(x,t);return(n>0,n,n>0?null:"No se guardó la deducción.");}public async ValueTask<(bool Succeeded,int Number,string?Error)>SaveLoanAsync(LoanInput x,CancellationToken t){if(x.Amount<=0||x.FortnightPayment<=0||x.FortnightPayment>x.Amount)return(false,0,"Monto o cuota inválidos.");var n=await repository.SaveLoanAsync(x,t);return(n>0,n,n>0?null:"No se guardó el préstamo.");}public ValueTask<bool>AnnulAsync(string type,int number,CancellationToken t)=>repository.AnnulAsync(type.Trim().ToLowerInvariant(),number,t);}
